// Lee lo que manda Meta y prepara el mensaje para el agente.
// Meta también avisa "entregado" y "leído" (statuses): esos eventos no traen mensaje y se descartan acá.
const v = $json;
const m = v.messages?.[0];
if (!m) return [];

const texto = m.type === 'text' ? String(m.text?.body ?? '').trim() : '';

// Protección de la clave: se detecta y se saca del texto ANTES de que llegue a la IA o a la memoria.
// Se busca un CUIT (11 dígitos, con o sin guiones) y, aparte, un número de 4 a 6 dígitos.
const cuitMatch = texto.match(/\b\d{2}-?\d{8}-?\d\b/);
const sinCuit = cuitMatch ? texto.replace(cuitMatch[0], ' ') : texto;
const claveMatch = cuitMatch || /clave/i.test(texto) ? sinCuit.match(/(?<![\d-])\d{4,6}(?![\d-])/) : null;
const texto_para_ia = claveMatch ? texto.replace(claveMatch[0], '[CLAVE OCULTA]') : texto;

return [{
  json: {
    telefono: m.from,
    // Argentina: WhatsApp manda el número con 9 (549...), pero la API de Meta lo espera sin el 9 (54...)
    telefono_envio: String(m.from).replace(/^549/, '54'),
    nombre_perfil: v.contacts?.[0]?.profile?.name ?? '',
    message_id: m.id,
    tipo: m.type,
    texto_para_ia,
    cuit_detectado: cuitMatch ? cuitMatch[0] : '',
    clave: claveMatch ? claveMatch[0] : '',
  },
}];

// Arma el dato "Sesión" que recibe el agente a partir de la hoja Sesiones (filtrada por el teléfono)
const ahora = new Date().toISOString();
const filas = $input.all().map(i => i.json).filter(s => s.telefono);
const activa = filas.find(s => s.valida_hasta > ahora && s.estado !== 'Cerrada');
// Venció si quedó "Activa" en la hoja pero pasaron los 30 minutos: se avisa una sola vez
const vencida = !activa && filas.some(s => s.estado === 'Activa' && s.valida_hasta <= ahora);
return [{ json: activa
  ? { sesion: `identificado como ${activa.razon_social}`, id_transportista: activa.id_transportista, sesion_vencida: false }
  : { sesion: vencida ? 'no identificado (su sesión anterior venció por inactividad)' : 'no identificado', id_transportista: '', sesion_vencida: vencida } }];

