// Controla lo que devolvió el agente ANTES de mandarlo por WhatsApp
const msg = $('Preparar mensaje').first().json;
const ses = $('Contexto de sesión').first().json;
const salida = String($json.output ?? '');
const pasos = $json.intermediateSteps ?? [];

let r = null;
// Algunos modelos escriben su razonamiento entre <think> y </think> antes del JSON: se descarta
const limpio = salida.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```json|```/g, '').trim();
try { r = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1)); } catch (e) { r = null; }

const acciones = ['pedir_identificacion', 'informar', 'ofrecer_reclamo', 'reclamo_creado', 'cerrar', 'derivar', 'fuera_de_alcance', 'cerrar_sesion'];
const RESPALDO = 'En este momento no es posible procesar su consulta. Un analista se comunicará con usted por correo electrónico.';

// Lo que hizo de verdad el agente se toma de los pasos, no de lo que dice
const obs = p => { try { return typeof p.observation === 'string' ? JSON.parse(p.observation) : p.observation; } catch (e) { return {}; } };
const herramientas = [...new Set(pasos.map(p => p.action?.tool).filter(Boolean))];
// La herramienta devuelve una lista con un objeto: se toma el primero
const reclamo = pasos.map(obs).map(o => (Array.isArray(o) ? o[0] : o)).map(o => o?.resultado ?? o).find(o => o?.id_reclamo);

// Si una herramienta falló (por ejemplo, el workflow de herramientas está apagado), la IA podría seguir la charla como si nada:
// se detecta acá y se responde con el mensaje de respaldo
const falloHerramienta = pasos.some(p => /There was an error|"error"\s*:/i.test(typeof p.observation === 'string' ? p.observation : JSON.stringify(p.observation ?? '')));

let respuesta = r && typeof r.respuesta === 'string' ? r.respuesta.trim() : '';
let accion = r && acciones.includes(r.accion) ? r.accion : 'derivar';
let control_respuesta = 'ok';

if (!respuesta) { respuesta = RESPALDO; control_respuesta = 'reemplazada: respuesta vacía o con formato inválido'; }
else if (falloHerramienta) { respuesta = RESPALDO; accion = 'derivar'; control_respuesta = 'reemplazada: falló una herramienta'; }
// 1. No puede filtrarse la clave, un CUIT ajeno ni códigos internos
else if ((msg.clave && respuesta.includes(msg.clave)) || /\bT-\d{2}\b|TMS-\d|\bF-\d{4}\b|\b\d{2}-?\d{8}-?\d\b/.test(respuesta)) {
  respuesta = RESPALDO; control_respuesta = 'reemplazada: datos internos o sensibles en la respuesta';
}
// 2. No puede decir que abrió un reclamo si la herramienta no lo creó
else if (accion === 'reclamo_creado' && !reclamo) {
  respuesta = RESPALDO; control_respuesta = 'reemplazada: dijo reclamo sin crearlo';
}
// 3. No puede prometer plazos que nadie definió ("en 48 horas hábiles"): pasó en el ensayo del 7/11
else if (/\b\d+\s*(horas|hs\.?|d[ií]as)\b/i.test(respuesta)) {
  respuesta = reclamo ? `Registramos su reclamo ${reclamo.id_reclamo}. Un analista lo va a revisar y le vamos a responder por correo electrónico. Quedamos a su disposición.` : RESPALDO;
  control_respuesta = 'reemplazada: prometió un plazo que no viene de una herramienta';
}
// 4. WhatsApp: corto
else if (respuesta.length > 700) { respuesta = respuesta.slice(0, 680).replace(/\s\S*$/, '') + '…'; control_respuesta = 'recortada'; }

// Avisos de sesión: los escribe el flujo, no la IA, para que salgan siempre igual
const cierra_sesion = accion === 'cerrar_sesion' && !!ses.id_transportista;
if (cierra_sesion) respuesta += '\n\nSu sesión ha finalizado. Para realizar una nueva consulta deberá identificarse nuevamente con su CUIT y clave.';
if (ses.sesion_vencida) respuesta = 'Su sesión anterior finalizó por inactividad (30 minutos).\n\n' + respuesta;

return [{
  json: {
    respuesta, accion, comprobante: r?.comprobante ?? '',
    // Campos que agrega este nodo (no los genera la IA):
    telefono: msg.telefono,
    message_id: msg.message_id,
    id_transportista: ses.id_transportista || '',
    herramientas_usadas: herramientas.join(', '),
    id_reclamo: reclamo?.id_reclamo ?? '',
    control_respuesta,
    cierra_sesion,
    avisar_analista: control_respuesta.startsWith('reemplazada'),
    mensaje_original: msg.texto_para_ia,
  },
}];

